function validate([length, width, height, mass]) {
  for (const value of [length, width, height]) {
    if (!Number.isInteger(value) || value < 1 || value > 100000) return 'Each side is a whole number from 1 to 10^5.';
  }
  if (!Number.isInteger(mass) || mass < 1 || mass > 1000) return 'mass is a whole number from 1 to 1000.';
  return null;
}

