function categorizeBox(length, width, height, mass) {
  const sideLimit = 10 ** 4;
  const volumeLimit = 10 ** 9;
  const volume = length * width * height;
  const bulky = length >= sideLimit || width >= sideLimit || height >= sideLimit || volume >= volumeLimit;
  const heavy = mass >= 100;
  if (bulky && heavy) {
    return "Both";
  }
  if (bulky) {
    return "Bulky";
  }
  if (heavy) {
    return "Heavy";
  }
  return "Neither";
}

