function categorizeBox(length, width, height, mass) {
  const big = Math.max(length, width, height) >= 10000 || BigInt(length) * BigInt(width) * BigInt(height) >= 1000000000n;
  const names = ["Neither", "Heavy", "Bulky", "Both"];
  return names[(big ? 2 : 0) + (mass >= 100 ? 1 : 0)];
}

