function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const side = () => {
    const r = rand();
    if (r < 0.15) return pick([9999, 10000, 100000, 1, 1000]);
    if (r < 0.55) return 1 + Math.floor(rand() * 2000);
    if (size === 'large' && r < 0.75) return 1 + Math.floor(rand() * 100000);
    return 500 + Math.floor(rand() * 3000);
  };
  const mass = rand() < 0.3 ? pick([1, 99, 100, 1000]) : 1 + Math.floor(rand() * 200);
  return [side(), side(), side(), mass];
}
